  "ask.blank": { zh: "例如 {examples}：在「其他」中填写，将 __ 替换为孩子的名字", en: "e.g. {examples}: write it under Other, with your child's name for __", ja: "例：{examples}（「その他」に、__ をお子さんの名前にして書いてください）" },
